      'على المستوى العصبي: الضغط يرفع الكورتيزول والأدرينالين والنورأدرينالين، بينما الاحتراق المزمن ينهك الغدد الكظرية ويخفض الدوبامين والسيروتونين.',
      'يتحول الضغط إلى احتراق وفق المعادلة: ضغط مزمن + نقص الموارد والدعم + غياب التعافي؛ بينما تحمي العدالة والوضوح والسيطرة والحدود من هذا التحول.',
      'علاج الضغط هو «الإدارة» (حل المشكلات، إدارة الوقت، الاسترخاء)، بينما علاج الاحتراق هو «التعافي» (التوقف الفوري، العناية الجسدية المكثفة، العلاج النفسي، والحدود الصارمة).',
      'عند الإصابة بـ «الاحتراق تحت الضغط» (وجود الحالتين معاً)، يجب علاج الاحتراق والتوقف للاسترداد أولاً قبل محاولة إدارة الضغوط.'
